{
  "metadata": {
    "providerId": "controlled",
    "modelId": "gpt-6.1-sol",
    "fields": [
      {
        "kind": "set",
        "key": "configured-model-id",
        "prominent": false,
        "value": "gpt-6.1-sol"
      },
      {
        "kind": "unset",
        "key": "openai.reasoning_mode",
        "prominent": true,
        "description": "Responses execution mode for GPT-5.6/GPT-6. Unset uses the API standard mode; pro uses more model work, tokens and latency. Independent of reasoning_effort. Omit for unsupported models."
      },
      {
        "kind": "unset",
        "key": "openai.reasoning_effort",
        "prominent": true,
        "description": "Reasoning effort is model dependent. GPT-6 Astra and GPT-6.1 Sol require low or higher; minimal is retained for older models.",
        "documentedDefault": "high"
      },
      {
        "kind": "unset",
        "key": "openai.service_tier",
        "prominent": true,
        "description": "Responses `service_tier` request parameter."
      },
      {
        "kind": "unset",
        "key": "openai.verbosity",
        "prominent": true,
        "description": "Responses text verbosity/detail level (when supported by the model).",
        "documentedDefault": "medium"
      },
      {
        "kind": "unset",
        "key": "openai.text_format",
        "prominent": true,
        "description": "Responses `text.format.type`. Prefer `json_schema` over legacy `json_object`.",
        "documentedDefault": "text"
      },
      {
        "kind": "unset",
        "key": "openai.web_search_tool",
        "prominent": true,
        "description": "Enable native Responses `tools: [{type:'web_search'}]`."
      }
    ]
  },
  "presentation": {
    "compactLabel": "controlled/gpt-6.1-sol·unset·unset·unset·unset·unset·unset",
    "tooltip": "provider-id: controlled\nmodel-id: gpt-6.1-sol\n\nconfigured-model-id: gpt-6.1-sol\n\nopenai.reasoning_mode: unset\nResponses execution mode for GPT-5.6/GPT-6. Unset uses the API standard mode; pro uses more model work, tokens and latency. Independent of reasoning_effort. Omit for unsupported models.\n\nopenai.reasoning_effort: unset\nReasoning effort is model dependent. GPT-6 Astra and GPT-6.1 Sol require low or higher; minimal is retained for older models.\ndocumented-default: high\n\nopenai.service_tier: unset\nResponses `service_tier` request parameter.\n\nopenai.verbosity: unset\nResponses text verbosity/detail level (when supported by the model).\ndocumented-default: medium\n\nopenai.text_format: unset\nResponses `text.format.type`. Prefer `json_schema` over legacy `json_object`.\ndocumented-default: text\n\nopenai.web_search_tool: unset\nEnable native Responses `tools: [{type:'web_search'}]`."
  }
}

