        members: { executor: { name: 'Executor', model_params: { reasoning_mode: 'pro' } } },
      };
      await fs.writeFile('.minds/team.yaml', YAML.stringify(misplaced));
      await Team.load();
      const misplacedProblem = getProblemsSnapshot().problems.find(
        (value) =>
